function SubmitButton({ isUpdate }: { isUpdate: boolean }) {
    const { pending } = useFormStatus();
    return (
        <Button type="submit" className="w-full" size="lg" disabled={pending}>
            {pending ? (isUpdate ? "更新中..." : "登録中...") : (isUpdate ? "カードを更新する" : "登録を完了する")}
